1	<!doctype html>
2	<html lang="zh-CN">
3	<meta charset="utf-8">
4	<meta name="viewport" content="width=device-width,initial-scale=1">
5	<title>ScoreArena · 桌面规则游戏与赛事管理</title>
6	<style>
7	  :root { color-scheme: light; }
8	  body { font-family: system-ui, sans-serif; max-width: 52rem; margin: 3rem auto; padding: 0 1rem; line-height: 1.7; color: #1f2933; }
9	  h1 { margin-bottom: .25rem; }
10	  .sub { color: #52606d; margin-top: 0; }
11	  h2 { margin-top: 2.5rem; border-bottom: 1px solid #e4e7eb; padding-bottom: .35rem; }
12	  a { color: #175b9c; }
13	  form { background: #f8f9fb; border: 1px solid #e4e7eb; border-radius: .5rem; padding: 1.25rem 1.5rem; }
14	  .field { display: grid; grid-template-columns: 9rem 1fr; gap: .75rem; align-items: center; margin-bottom: 1rem; }
15	  label { font-weight: 600; }
16	  input, select { font: inherit; padding: .4rem .55rem; border: 1px solid #cbd2d9; border-radius: .35rem; background: #fff; }
17	  input:focus, select:focus { outline: 2px solid #9ec5fe; outline-offset: 1px; border-color: #175b9c; }
18	  .hint { grid-column: 2; color: #616e7c; font-size: .9rem; margin: -.35rem 0 0; }
19	  .actions { grid-column: 2; margin-top: .25rem; }
20	  button { font: inherit; font-weight: 600; padding: .5rem 1.4rem; border: none; border-radius: .35rem; background: #175b9c; color: #fff; cursor: pointer; }
21	  button:disabled { background: #9aa5b1; cursor: wait; }
22	  .msg { margin: 1rem 0 0; padding: .6rem .9rem; border-radius: .35rem; display: none; }
23	  .msg.show { display: block; }
24	  .msg.error { background: #fde8e8; border: 1px solid #f5b5b5; color: #9b1c1c; }
25	  .msg.ok { background: #e6f6ec; border: 1px solid #a7e0bd; color: #146134; }
26	  table { width: 100%; border-collapse: collapse; font-size: .95rem; }
27	  th, td { text-align: left; padding: .55rem .6rem; border-bottom: 1px solid #e4e7eb; vertical-align: top; }
28	  th { color: #52606d; font-size: .85rem; white-space: nowrap; }
29	  td.id, code { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: .85rem; word-break: break-all; }
30	  .empty { color: #616e7c; }
31	  .skip-notice { background: #fff8e6; border: 1px solid #f0d48a; color: #7c4a03; padding: .6rem .9rem; border-radius: .35rem; margin: 0 0 1rem; }
32	  .list-error { color: #9b1c1c; }
33	  .badge { display: inline-block; padding: .05rem .55rem; border-radius: 999px; background: #fff3c4; color: #7c4a03; font-size: .85rem; }
34	  .meta { color: #7b8794; font-size: .85rem; }
35	</style>
36	<main>
37	  <h1>ScoreArena</h1>
38	  <p class="sub">桌面规则游戏与赛事管理</p>
39	
40	  <h2>创建公开房间</h2>
41	  <form id="room-form" novalidate>
42	    <div class="field">
43	      <label for="name">房间名称</label>
44	      <input id="name" name="name" type="text" autocomplete="off"
45	             placeholder="1–40 个字符，首尾空白会被去掉" required>
46	      <p class="hint">名称会去掉首尾空白后保存，内部空格保留；长度按 Unicode 字符计。原始输入不限长，整理后不超过 40 个字符即可。</p>
47	    </div>
48	    <div class="field">
49	      <label for="game">游戏规则</label>
50	      <select id="game" name="game" required>
51	        <option value="" selected>请选择游戏规则…</option>
52	        <option value="gomoku">五子棋（gomoku）</option>
53	        <option value="ludo">飞行棋（ludo）</option>
54	      </select>
55	    </div>
56	    <div class="field">
57	      <label for="capacity">人数上限</label>
58	      <select id="capacity" name="capacity" required disabled>
59	        <option value="" selected>请先选择游戏规则</option>
60	      </select>
61	      <p class="hint" id="capacity-hint">五子棋人数固定为 2 人；飞行棋允许 2 至 4 人。</p>
62	    </div>
63	    <div class="field">
64	      <label for="turnSeconds">每步时间限制</label>
65	      <input id="turnSeconds" name="turnSeconds" type="number" step="1" inputmode="numeric"
66	             placeholder="秒，0 表示不限时" required>
67	      <p class="hint">以秒为单位：填 <strong>0</strong> 表示不限时；其他值必须是 10 至 600 之间的整数。</p>
68	    </div>
69	    <div class="field">
70	      <div></div>
71	      <div class="actions">
72	        <button type="submit" id="submit">创建房间</button>
73	      </div>
74	    </div>
75	    <p class="msg" id="form-msg" role="alert"></p>
76	  </form>
77	
78	  <h2>房间列表</h2>
79	  <div id="list-area">
80	    <p class="empty" id="empty-tip">还没有房间记录。</p>
81	  </div>
82	
83	  <p class="meta"><a href="/api/rooms">查看房间列表接口</a> · <a href="/health">服务状态</a></p>
84	</main>
85	
86	<script>
87	(function () {
88	  var form = document.getElementById('room-form');
89	  var gameSel = document.getElementById('game');
90	  var capSel = document.getElementById('capacity');
91	  var capHint = document.getElementById('capacity-hint');
92	  var submitBtn = document.getElementById('submit');
93	  var formMsg = document.getElementById('form-msg');
94	  var listArea = document.getElementById('list-area');
95	  var emptyTip = document.getElementById('empty-tip');
96	
97	  var GAME_LABELS = { gomoku: '五子棋', ludo: '飞行棋' };
98	  var STATUS_LABELS = { waiting: '未开始' };
99	
100	  // 按所选规则重建人数上限选项。
101	  function syncCapacity() {
102	    var game = gameSel.value;
103	    var prev = capSel.value;
104	    capSel.innerHTML = '';
105	    if (game === 'gomoku') {
106	      capSel.disabled = false;
107	      addOption('', '固定 2 人');
108	      addOption('2', '2 人');
109	      capSel.value = '2';
110	      capHint.textContent = '五子棋人数上限固定为 2 人。';
111	    } else if (game === 'ludo') {
112	      capSel.disabled = false;
113	      addOption('', '请选择人数上限…');
114	      [2, 3, 4].forEach(function (n) { addOption(String(n), n + ' 人'); });
115	      capSel.value = (prev === '2' || prev === '3' || prev === '4') ? prev : '';
116	      capHint.textContent = '飞行棋人数上限允许 2 至 4 人。';
117	    } else {
118	      capSel.disabled = true;
119	      addOption('', '请先选择游戏规则');
120	      capHint.textContent = '五子棋人数固定为 2 人；飞行棋允许 2 至 4 人。';
121	    }
122	  }
123	
124	  function addOption(value, text) {
125	    var opt = document.createElement('option');
126	    opt.value = value;
127	    opt.textContent = text;
128	    capSel.appendChild(opt);
129	  }
130	
131	  gameSel.addEventListener('change', syncCapacity);
132	
133	  function showMessage(kind, text) {
134	    formMsg.className = 'msg show ' + kind;
135	    formMsg.textContent = text;
136	  }
137	  function clearMessage() {
138	    formMsg.className = 'msg';
139	    formMsg.textContent = '';
140	  }
141	
142	  // 与服务端 strings.TrimSpace（Go unicode.IsSpace）完全一致的首尾空白范围：
143	  // 包含 U+0085、U+00A0 等，但不包含 U+FEFF（保留并计入长度）。
144	  // 不能用 JS 自带的 trim()：它会多去掉 U+FEFF，又漏掉 U+0085。
145	  var EDGE_SPACE = '[\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]';
146	  var LEADING_SPACE = new RegExp('^' + EDGE_SPACE + '+');
147	  var TRAILING_SPACE = new RegExp(EDGE_SPACE + '+$');
148	  function trimName(value) {
149	    return value.replace(LEADING_SPACE, '').replace(TRAILING_SPACE, '');
150	  }
151	
152	  // 与服务端一致的提交前校验；服务端仍会再次校验。
153	  // 输入表单原始值，返回 { error } 或 { payload }：漏填要明确报错，绝不补默认值；
154	  // 名称只含会被去掉的首尾空白时同样视为空。通过校验的 payload 中名称仍是
155	  // 用户原始输入（不由页面整理），时间与人数各只转换一次。
156	  function checkForm(raw) {
157	    var nameLen = Array.from(trimName(raw.name)).length;
158	    if (nameLen === 0) return { error: '房间名称不能为空。' };
159	    if (!raw.game) return { error: '请选择游戏规则。' };
160	    if (raw.capacity === '') return { error: '请选择人数上限。' };
161	    if (raw.turnSeconds === '') return { error: '请填写每步时间限制（0 表示不限时）。' };
162	    if (!/^-?\d+$/.test(raw.turnSeconds)) return { error: '时间限制必须是整数秒，不能含小数。' };
163	
164	    // 通过必填与整数格式检查后再转换：空值不会变成 0，不合法文字不会变成秒数。
165	    var capacity = parseInt(raw.capacity, 10);
166	    var turnSeconds = Number(raw.turnSeconds);
167	
168	    if (nameLen > 40) return { error: '房间名称去掉首尾空白后不能超过 40 个字符。' };
169	    if (raw.game !== 'gomoku' && raw.game !== 'ludo') return { error: '请选择游戏规则。' };
170	    if (raw.game === 'gomoku' && capacity !== 2) return { error: '五子棋的人数上限固定为 2 人。' };
171	    if (raw.game === 'ludo' && !(capacity >= 2 && capacity <= 4)) {
172	      return { error: '飞行棋的人数上限必须为 2 至 4 人。' };
173	    }
174	    if (turnSeconds !== 0 && !(turnSeconds >= 10 && turnSeconds <= 600)) {
175	      return { error: '每步时间限制只能填 0（不限时）或 10 至 600 之间的整数秒。' };
176	    }
177	
178	    return {
179	      payload: {
180	        name: raw.name,
181	        game: raw.game,
182	        capacity: capacity,
183	        turnSeconds: turnSeconds
184	      }
185	    };
186	  }
187	
188	  form.addEventListener('submit', function (event) {
189	    event.preventDefault();
190	    clearMessage();
191	
192	    var result = checkForm({
193	      name: document.getElementById('name').value,
194	      game: gameSel.value,
195	      capacity: capSel.value,
196	      turnSeconds: document.getElementById('turnSeconds').value.trim()
197	    });
198	    if (result.error) { showMessage('error', result.error); return; }
199	
200	    submit(result.payload);
201	  });
202	
203	  function submit(payload) {
204	    submitBtn.disabled = true;
205	    fetch('/api/rooms', {
206	      method: 'POST',
207	      headers: { 'Content-Type': 'application/json' },
208	      body: JSON.stringify(payload)
209	    }).then(function (resp) {
210	      return resp.json().catch(function () { return {}; }).then(function (data) {
211	        return { ok: resp.ok, status: resp.status, data: data };
212	      });
213	    }).then(function (result) {
214	      if (result.ok && result.status === 201) {
215	        showMessage('ok', '房间已创建，编号：' + result.data.id);
216	        form.reset();
217	        syncCapacity();
218	        return loadRooms();
219	      }
220	      // 创建失败：保留填写内容，仅显示原因。
221	      var reason = result.data && result.data.error ? result.data.error
222	                 : ('创建失败（HTTP ' + result.status + '）');
223	      showMessage('error', reason);
224	    }).catch(function () {
225	      showMessage('error', '无法连接服务，请确认服务仍在运行后重试。');
226	    }).finally(function () {
227	      submitBtn.disabled = false;
228	    });
229	  }
230	
231	  function formatTime(iso) {
232	    var d = new Date(iso);
233	    if (isNaN(d.getTime())) return iso;
234	    var pad = function (n) { return String(n).padStart(2, '0'); };
235	    var text = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) +
236	      ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
237	    return { text: text, title: iso };
238	  }
239	
240	  // 只有 JSON 对象能作为房间行；null、字符串、数字、布尔值和数组都跳过。
241	  // 不按创建表单的规则重新判定历史记录：对象带多少附加字段都照常展示，
242	  // 也不检查其字段是否完整或合法（各单元格沿用现有兜底显示）。
243	  function isRoomRecord(value) {
244	    return value !== null && typeof value === 'object' && !Array.isArray(value);
245	  }
246	
247	  function appendSkipNotice(skipped, allSkipped) {
248	    var p = document.createElement('p');
249	    p.className = 'skip-notice';
250	    if (allSkipped) {
251	      p.textContent = '没有可展示的房间。本次返回的房间记录中有 ' + skipped +
252	        ' 条无法作为房间显示，已全部跳过；原始数据仍保留在服务端，未被删除或改写。';
253	    } else {
254	      p.textContent = '有 ' + skipped + ' 条房间记录无法作为房间显示，已跳过；' +
255	        '原始数据仍保留在服务端，未被删除或改写。';
256	    }
257	    listArea.appendChild(p);
258	  }
259	
260	  // 历史记录的某个展示字段若被存成 JSON 对象或数组，该单元格统一显示
261	  // “字段格式异常”，不展开其内部内容；异常只影响所在单元格，绝不能抛出
262	  // 异常拖垮整行乃至整份列表。null、字符串、数字、布尔值及缺失字段都不算
263	  // 异常，仍走各列原有的展示与兜底。
264	  var BAD_FIELD_TEXT = '字段格式异常';
265	  function isAbnormalField(value) {
266	    return value !== null && typeof value === 'object';
267	  }
268	  function markBadCell(td) {
269	    td.textContent = BAD_FIELD_TEXT;
270	  }
271	
272	  // 逐单元格渲染一个房间行：任何字段异常都只替换该单元格，其余字段照常显示。
273	  function buildRoomRow(r) {
274	    var tr = document.createElement('tr');
275	
276	    var tdId = document.createElement('td');
277	    tdId.className = 'id';
278	    if (isAbnormalField(r.id)) markBadCell(tdId);
279	    else tdId.textContent = r.id || '';
280	    tr.appendChild(tdId);
281	
282	    var tdName = document.createElement('td');
283	    if (isAbnormalField(r.name)) markBadCell(tdName);
284	    else tdName.textContent = r.name || '';
285	    tr.appendChild(tdName);
286	
287	    var tdGame = document.createElement('td');
288	    if (isAbnormalField(r.game)) markBadCell(tdGame);
289	    else tdGame.textContent = GAME_LABELS[r.game] || r.game || '';
290	    tr.appendChild(tdGame);
291	
292	    var tdCap = document.createElement('td');
293	    if (isAbnormalField(r.capacity)) markBadCell(tdCap);
294	    else tdCap.textContent = (r.capacity != null ? r.capacity : '') + ' 人';
295	    tr.appendChild(tdCap);
296	
297	    var tdTurn = document.createElement('td');
298	    if (isAbnormalField(r.turnSeconds)) {
299	      markBadCell(tdTurn);
300	    } else if (r.turnSeconds === 0) {
301	      tdTurn.textContent = '不限时';
302	    } else {
303	      tdTurn.textContent = r.turnSeconds + ' 秒';
304	    }
305	    tr.appendChild(tdTurn);
306	
307	    var tdStatus = document.createElement('td');
308	    var badge = document.createElement('span');
309	    badge.className = 'badge';
310	    if (isAbnormalField(r.status)) badge.textContent = BAD_FIELD_TEXT;
311	    else badge.textContent = STATUS_LABELS[r.status] || r.status || '';
312	    tdStatus.appendChild(badge);
313	    tr.appendChild(tdStatus);
314	
315	    var tdTime = document.createElement('td');
316	    if (isAbnormalField(r.createdAt)) {
317	      // 异常创建时间只显示异常文案，不附加日期悬浮说明（不设置 title）。
318	      markBadCell(tdTime);
319	    } else {
320	      var t = formatTime(r.createdAt || '');
321	      tdTime.textContent = t.text;
322	      tdTime.title = t.title;
323	    }
324	    tr.appendChild(tdTime);
325	
326	    return tr;
327	  }
328	
329	  function renderRooms(rooms) {
330	    listArea.innerHTML = '';
331	
332	    var validRooms = [];
333	    var skipped = 0;
334	    rooms.forEach(function (r) {
335	      if (isRoomRecord(r)) validRooms.push(r);
336	      else skipped++;
337	    });
338	
339	    if (!validRooms.length) {
340	      if (skipped > 0) {
341	        appendSkipNotice(skipped, true);
342	      } else {
343	        var pEmpty = document.createElement('p');
344	        pEmpty.className = 'empty';
345	        pEmpty.textContent = '还没有房间记录。';
346	        listArea.appendChild(pEmpty);
347	      }
348	      return;
349	    }
350	
351	    if (skipped > 0) appendSkipNotice(skipped, false);
352	
353	    var table = document.createElement('table');
354	    table.innerHTML =
355	      '<thead><tr>' +
356	      '<th>房间编号</th><th>名称</th><th>规则</th><th>人数上限</th>' +
357	      '<th>时间限制</th><th>状态</th><th>创建时间</th>' +
358	      '</tr></thead>';
359	    var tbody = document.createElement('tbody');
360	    validRooms.forEach(function (r) {
361	      tbody.appendChild(buildRoomRow(r));
362	    });
363	    table.appendChild(tbody);
364	    listArea.appendChild(table);
365	  }
366	
367	  // 列表查询序号：每次发起查询递增，只有当前最新一次查询的结果
368	  // （无论成功还是失败）允许更新列表区域；较早查询后返回的结果一律忽略，
369	  // 防止旧数据覆盖新查询已展示的列表。
370	  var listQuerySeq = 0;
371	
372	  function loadRooms() {
373	    var seq = ++listQuerySeq;
374	    return fetch('/api/rooms', { headers: { 'Accept': 'application/json' } })
375	      .then(function (resp) {
376	        if (!resp.ok) throw new Error('HTTP ' + resp.status);
377	        return resp.json();
378	      })
379	      .then(function (data) {
380	        if (seq !== listQuerySeq) return;
381	        var rooms = Array.isArray(data && data.rooms) ? data.rooms : [];
382	        renderRooms(rooms);
383	      })
384	      .catch(function () {
385	        if (seq !== listQuerySeq) return;
386	        listArea.innerHTML = '';
387	        var p = document.createElement('p');
388	        p.className = 'list-error';
389	        p.textContent = '房间列表加载失败，请稍后刷新重试。已有数据不会因此丢失。';
390	        listArea.appendChild(p);
391	      });
392	  }
393	
394	  syncCapacity();
395	  loadRooms();
396	})();
397	</script>
398	</html>
399

1	// 首页“创建公开房间”功能的界面回归测试。
2	//
3	// 与 main_test.go 的分工：main_test.go 通过公开 HTTP 接口验证创建与本地保存；
4	// 本文件用真实浏览器（系统 Chrome）加载真实服务的首页，模拟用户填写与提交，
5	// 断言用户在页面上实际看到的提示、表单与房间列表变化，重点区分两类请求结果：
6	//   1. POST /api/rooms 的创建结果（决定成功提示、编号与表单复位）；
7	//   2. 紧随其后的 GET /api/rooms 列表刷新结果（决定列表区域内容）。
8	// 两者不能混为一谈：创建被拒时列表不得新增记录；创建成功但列表刷新失败时，
9	// 成功提示与编号必须保留，列表区域必须显示加载失败而非“还没有房间记录”。
10	//
